package com.vandorlabs.neoforge.builders;
import com.vandorlabs.neoforge.transfer.*;import com.vandorlabs.neoforge.redstone.NativeRedstoneChannels;import com.vandorlabs.machines.CoreLayout;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.entity.BlockEntity;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.tick.LevelTickEvent;
@EventBusSubscriber(modid="vandorlabs")
public final class NativeBuilderTransactions {
 private static final NativeTransferSnapshot.Limits LIMITS=new NativeTransferSnapshot.Limits(128,65536,1024*1024,4*1024*1024);
 private record Recipe(String design,boolean form,int facing,int x,int z,BlockPos mined,boolean single,boolean coreDrop,boolean dropsEnabled,List<NativeBuilderDrops.Drop> drops){}
 private record Pending(ServerPlayer actor,NativeBuilderEntity owner,NativeCellTransactions.Request request){}
 private static final Map<ServerLevel,Map<BlockPos,Pending>> QUEUED=new IdentityHashMap<>();
 public static void register(){NativeCellTransactions.register(FAMILY);}
 private static List<BlockPos> footprint(BlockPos root,NativeBuilderDesigns.Design d,CoreLayout l){var out=new ArrayList<BlockPos>();for(int y=0;y<d.height();y++)for(int x=0;x<d.width();x++)for(int z=0;z<d.depth();z++)out.add(root.offset(l.x(x,z),y,l.z(x,z)));return out;}
 private static NativeRawCell capture(ServerLevel w,BlockPos p){if(!NativeBuilderFormation.loaded(w,p))throw new IllegalArgumentException("Load the complete builder");var t=w.getBlockEntity(p);return new NativeRawCell(p,w.getBlockState(p),t==null?null:t.saveWithFullMetadata(w.registryAccess()),LIMITS.tileBytes());}
 public static boolean request(NativeBuilderEntity owner,ServerPlayer actor,boolean form){return request(owner,actor,form,null);}
 public static boolean mine(NativeBuilderEntity owner,ServerPlayer actor,BlockPos at){return request(owner,actor,false,at);}
 private static boolean request(NativeBuilderEntity owner,ServerPlayer actor,boolean form,BlockPos mined){boolean single=mined!=null&&mined.equals(owner.getBlockPos())&&!owner.formed();if(!owner.available()||owner.formed()==form&&!single)return false;var world=actor.serverLevel();var found=form?NativeBuilderFormation.discover(owner):new NativeBuilderFormation.Layout(owner.facing(),owner.layout().cornerX,owner.layout().cornerZ);var d=owner.design();var l=new CoreLayout(d.width(),d.height(),d.depth(),found.facing().get3DDataValue(),found.x(),found.z());var before=new ArrayList<NativeRawCell>();var after=new ArrayList<NativeRawCell>();var cells=single?List.of(owner.getBlockPos()):footprint(owner.getBlockPos(),d,l);
  for(var p:cells){var raw=capture(world,p);before.add(raw);if(p.equals(owner.getBlockPos())){var state=raw.state.setValue(NativeBuilderCoreBlock.FACING,found.facing()).setValue(NativeBuilderCoreBlock.FORMED,form);var tile=new NativeBuilderEntity(p,state);tile.setLevel(world);tile.loadWithComponents(raw.tile(),world.registryAccess());tile.corner(found.x(),found.z());after.add(mined!=null&&mined.equals(p)?new NativeRawCell(p,Blocks.AIR.defaultBlockState(),null,LIMITS.tileBytes()):new NativeRawCell(p,state,tile.saveWithFullMetadata(world.registryAccess()),LIMITS.tileBytes()));}else{int y=p.getY()-owner.getBlockPos().getY();int localX=0,localZ=0;for(int x=0;x<d.width();x++)for(int z=0;z<d.depth();z++)if(owner.getBlockPos().offset(l.x(x,z),y,l.z(x,z)).equals(p)){localX=x;localZ=z;}boolean frame=l.frame(localX,y,localZ);if(form){var state=NativeBuilderBindings.PART.defaultBlockState();var part=new NativeBuilderPartEntity(p,state);part.setLevel(world);part.owner(owner.getBlockPos());after.add(new NativeRawCell(p,state,part.saveWithFullMetadata(world.registryAccess()),LIMITS.tileBytes()));}else after.add(new NativeRawCell(p,frame&&!p.equals(mined)?NativeBuilderFormation.matter().defaultBlockState():Blocks.AIR.defaultBlockState(),null,LIMITS.tileBytes()));}}
  var encoded=new CompoundTag();encoded.putString("Design",d.id());encoded.putBoolean("Form",form);encoded.putInt("Facing",found.facing().get3DDataValue());encoded.putInt("X",found.x());encoded.putInt("Z",found.z());if(single)encoded.putBoolean("Unformed",true);if(mined!=null){boolean dropsEnabled=world.getGameRules().getBoolean(net.minecraft.world.level.GameRules.RULE_DOBLOCKDROPS),coreDrop=mined.equals(owner.getBlockPos())&&!actor.isCreative()&&dropsEnabled&&actor.hasCorrectToolForDrops(owner.getBlockState());encoded.putBoolean("CoreDrop",coreDrop);encoded.putBoolean("DropsEnabled",dropsEnabled);encoded.putLong("Mined",mined.asLong());var drops=new ListTag();for(var item:loot(world.registryAccess(),before,owner.getBlockPos(),mined,actor.isCreative(),coreDrop,dropsEnabled,d,l)){var drop=new CompoundTag();drop.putUUID("Id",UUID.randomUUID());drop.put("Item",item.save(world.registryAccess()));drops.add(drop);}encoded.put("Drops",drops);}var request=new NativeCellTransactions.Request(owner.getBlockPos(),owner.key(),new NativeTransferSnapshot(before,LIMITS),new NativeTransferSnapshot(after,LIMITS),cells,encoded);FAMILY.readRecipe(world.registryAccess(),new NativeCellTransactions.Header(UUID.randomUUID(),FAMILY.id(),owner.getBlockPos(),owner.key(),actor.getUUID(),actor.isCreative()),request.before(),request.after(),Set.copyOf(cells),encoded);owner.pending(true);QUEUED.computeIfAbsent(world,k->new LinkedHashMap<>()).put(owner.getBlockPos(),new Pending(actor,owner,request));return true;
 }
 private static final NativeCellTransactions.Family<Recipe> FAMILY=new NativeCellTransactions.Family<>(){
  public ResourceLocation id(){return ResourceLocation.parse("vandorlabs:builder_formation");}public NativeTransferSnapshot.Limits limits(){return LIMITS;}
  public Recipe readRecipe(HolderLookup.Provider regs,NativeCellTransactions.Header h,NativeTransferSnapshot before,NativeTransferSnapshot after,Set<BlockPos> held,CompoundTag tag){boolean mining=tag.contains("Mined"),single=tag.contains("Unformed");var keys=new HashSet<>(Set.of("Design","Form","Facing","X","Z"));if(mining)keys.addAll(Set.of("Mined","Drops","CoreDrop","DropsEnabled"));if(single)keys.add("Unformed");if(!tag.getAllKeys().equals(keys)||!tag.contains("Design",8)||!tag.contains("Form",1)||tag.getByte("Form")<0||tag.getByte("Form")>1||!tag.contains("Facing",3)||!tag.contains("X",3)||!tag.contains("Z",3))throw new IllegalArgumentException("Builder recipe schema");var d=NativeBuilderDesigns.find(tag.getString("Design"));int f=tag.getInt("Facing"),x=tag.getInt("X"),z=tag.getInt("Z");boolean form=tag.getBoolean("Form");BlockPos mined=mining?BlockPos.of(tag.getLong("Mined")):null;if(mining&&(form||!tag.contains("Mined",4)||!(tag.get("Drops") instanceof ListTag list)||!list.isEmpty()&&list.getElementType()!=10))throw new IllegalArgumentException("Builder mine schema");if(single&&(!mining||!h.root().equals(mined)||!tag.contains("Unformed",1)||tag.getByte("Unformed")!=1))throw new IllegalArgumentException("Unformed owner mine receipt");var l=new CoreLayout(d.width(),d.height(),d.depth(),f,x,z);if(!l.canonicalCorner())throw new IllegalArgumentException("Builder corner");var expected=single?Set.of(h.root()):Set.copyOf(footprint(h.root(),d,l));if(!expected.equals(held)||before.cells().size()!=expected.size()||after.cells().size()!=expected.size())throw new IllegalArgumentException("Builder footprint");var old=new HashMap<BlockPos,NativeRawCell>();var next=new HashMap<BlockPos,NativeRawCell>();for(var c:before.cells())old.put(c.pos,c);for(var c:after.cells())next.put(c.pos,c);if(!old.keySet().equals(expected)||!next.keySet().equals(expected))throw new IllegalArgumentException("Builder cell set");for(int a=0;a<d.width();a++)for(int y=0;y<d.height();y++)for(int b=0;b<d.depth();b++){var p=h.root().offset(l.x(a,b),y,l.z(a,b));if(single&&!p.equals(h.root()))continue;var from=old.get(p);var to=next.get(p);if(p.equals(h.root())){if(!(from.state.getBlock() instanceof NativeBuilderCoreBlock core)||!core.design.equals(d)||(single?from.state.getValue(NativeBuilderCoreBlock.FORMED):from.state.getValue(NativeBuilderCoreBlock.FORMED)==form)||!from.hasTile())throw new IllegalArgumentException("Builder core morph");var raw=from.tile();if(!raw.hasUUID("BuilderKey")||!raw.getUUID("BuilderKey").equals(h.owner()))throw new IllegalArgumentException("Builder identity");if(!form&&(from.state.getValue(NativeBuilderCoreBlock.FACING).get3DDataValue()!=f||raw.getInt("ConstructorCoreX")!=x||raw.getInt("ConstructorCoreZ")!=z))throw new IllegalArgumentException("Builder saved facing/corner changed");if(p.equals(mined)){if(!to.state.isAir()||to.hasTile())throw new IllegalArgumentException("Mined core must be absent");}else{if(to.state!=from.state.setValue(NativeBuilderCoreBlock.FACING,Direction.from3DDataValue(f)).setValue(NativeBuilderCoreBlock.FORMED,form)||!to.hasTile())throw new IllegalArgumentException("Builder core state");raw.putInt("ConstructorCoreX",x);raw.putInt("ConstructorCoreZ",z);if(!NativeBuilderData.sameSnapshots(raw,to.tile()))throw new IllegalArgumentException("Builder core inventory changed");}}else{var plain=l.frame(a,y,b)?NativeBuilderFormation.matter().defaultBlockState():Blocks.AIR.defaultBlockState();var reservation=form?to:from;var original=form?from:to;if(original.state!=(p.equals(mined)?Blocks.AIR.defaultBlockState():plain)||original.hasTile()||reservation.state.getBlock()!=NativeBuilderBindings.PART||!reservation.hasTile())throw new IllegalArgumentException("Builder frame morph");var raw=NativeBuilderData.normalizedSnapshot(reservation.tile());if(!raw.contains("ConstructorOwner",4)||!BlockPos.of(raw.getLong("ConstructorOwner")).equals(h.root().subtract(p))||raw.contains("BuilderOwner")&&(!raw.hasUUID("BuilderOwner")||!raw.getUUID("BuilderOwner").equals(h.owner()))||raw.getAllKeys().stream().anyMatch(k->!Set.of("id","x","y","z","ConstructorOwner","BuilderOwner").contains(k)))throw new IllegalArgumentException("Builder reservation owner");}}boolean coreDrop=tag.getBoolean("CoreDrop"),dropsEnabled=tag.getBoolean("DropsEnabled");var drops=new ArrayList<NativeBuilderDrops.Drop>();if(mining){for(var k:List.of("CoreDrop","DropsEnabled"))if(!tag.contains(k,1)||tag.getByte(k)<0||tag.getByte(k)>1)throw new IllegalArgumentException("Builder loot policy type");if(coreDrop&&(h.creative()||!h.root().equals(mined)||!dropsEnabled))throw new IllegalArgumentException("Builder core drop policy");if(!expected.contains(mined))throw new IllegalArgumentException("Mined cell outside builder");var encoded=tag.getList("Drops",10);var expectedLoot=loot(regs,before.cells(),h.root(),mined,h.creative(),coreDrop,dropsEnabled,d,l);if(encoded.size()!=expectedLoot.size()||encoded.size()>16)throw new IllegalArgumentException("Builder mined loot count");var ids=new HashSet<UUID>();for(int i=0;i<encoded.size();i++){var row=encoded.getCompound(i);if(!row.getAllKeys().equals(Set.of("Id","Item"))||!row.hasUUID("Id")||!row.contains("Item",10)||!ids.add(row.getUUID("Id")))throw new IllegalArgumentException("Builder loot schema");var item=ItemStack.parse(regs,row.getCompound("Item")).orElseThrow();if(!ItemStack.matches(item,expectedLoot.get(i))||!row.getCompound("Item").equals(item.save(regs)))throw new IllegalArgumentException("Builder mine ownership receipt");drops.add(new NativeBuilderDrops.Drop(row.getUUID("Id"),item));}}return new Recipe(d.id(),form,f,x,z,mined,single,coreDrop,dropsEnabled,List.copyOf(drops));}
  public void authorize(ServerLevel world,NativeCellTransactions.Header h,ServerPlayer actor,Recipe r){if(!(world.getBlockEntity(h.root()) instanceof NativeBuilderEntity root)||root.inert()||!root.key().equals(h.owner())||actor.distanceToSqr(h.root().getCenter())>256)throw new IllegalArgumentException("Builder owner/player changed");if(r.mined!=null&&(r.dropsEnabled!=world.getGameRules().getBoolean(net.minecraft.world.level.GameRules.RULE_DOBLOCKDROPS)||r.coreDrop!=(r.mined.equals(h.root())&&!actor.isCreative()&&r.dropsEnabled&&actor.hasCorrectToolForDrops(root.getBlockState()))))throw new IllegalArgumentException("Builder harvest tool/rule changed while preparing");var d=NativeBuilderDesigns.find(r.design);var l=new CoreLayout(d.width(),d.height(),d.depth(),r.facing,r.x,r.z);for(var p:r.single?List.of(h.root()):footprint(h.root(),d,l))if(!NativeBuilderFormation.loaded(world,p)||!world.mayInteract(actor,p)||!actor.mayUseItemAt(p,Direction.UP,actor.getMainHandItem()))throw new IllegalArgumentException("Builder cell permission");}
  public BlockEntity stage(ServerLevel world,NativeCellTransactions.Header h,NativeRawCell cell,Recipe r){return cell.stage(world,t->t instanceof NativeBuilderEntity||t instanceof NativeBuilderPartEntity,this::same);}public boolean same(CompoundTag a,CompoundTag b){return NativeBuilderData.sameSnapshots(a,b);}
  public void publish(ServerLevel world,NativeCellTransactions.Header h,NativeRawCell before,NativeRawCell after,BlockEntity staged,NativeTransferHolds.Lease lease,Recipe r){if(world.getBlockState(after.pos)!=after.state)try(var scope=lease.allowOnce(after.pos)){if(!NativeBuilderProtection.set(world,after.pos,after.state,Block.UPDATE_KNOWN_SHAPE))throw new IllegalStateException("Builder publication refused");}if(after.hasTile()){world.removeBlockEntity(after.pos);world.setBlockEntity(staged);staged.setChanged();}else world.removeBlockEntity(after.pos);world.getChunkAt(after.pos).setUnsaved(true);}
  public boolean readyAdditional(ServerLevel w,NativeCellTransactions.Header h,boolean rollback,Recipe r){return r.mined==null||NativeBuilderDrops.ready(w,h,r.mined,r.drops,rollback);}
  public void installAdditional(ServerLevel w,NativeCellTransactions.Header h,Recipe r){if(r.mined!=null)NativeBuilderDrops.install(w,h,r.mined,r.drops);}
  public void rollbackAdditional(ServerLevel w,NativeCellTransactions.Header h,Recipe r){if(r.mined!=null)NativeBuilderDrops.rollback(w,h,r.mined,r.drops);}
  public boolean additionalMatches(ServerLevel w,NativeCellTransactions.Header h,boolean rollback,Recipe r){return r.mined==null||NativeBuilderDrops.matches(w,h,r.mined,r.drops,rollback);}
  public boolean checkpointAdditional(ServerLevel w,NativeCellTransactions.Header h,boolean rollback,Recipe r){return r.mined==null||NativeBuilderDrops.checkpoint(w,h,r.mined,r.drops,rollback);}
  public void released(ServerLevel world,NativeCellTransactions.Header h,boolean rollback,String error,Recipe r){NativeBuilderDrops.released(world,h);if(world.getBlockEntity(h.root()) instanceof NativeBuilderEntity root){root.pending(false);root.changed();NativeRedstoneChannels.queueRegistration(root);}var d=NativeBuilderDesigns.find(r.design);var layout=new CoreLayout(d.width(),d.height(),d.depth(),r.facing,r.x,r.z);/* Same-state updates also send fresh part-owner NBT through the normal chunk packet path, after retirement. */var cells=r.single?List.of(h.root()):footprint(h.root(),d,layout);for(var pos:cells){if(!NativeBuilderFormation.loaded(world,pos))continue;world.invalidateCapabilities(pos);var state=world.getBlockState(pos);world.sendBlockUpdated(pos,state,state,Block.UPDATE_CLIENTS);}}
 };
 static boolean escrowReleased(ServerLevel w,CompoundTag marker,UUID drop){return NativeCellTransactions.escrowState(w,FAMILY,marker.getUUID("Operation"),BlockPos.of(marker.getLong("Root")),marker.getUUID("Owner"),marker.getUUID("Actor"),r->r.drops.stream().anyMatch(d->d.id().equals(drop)))==NativeCellTransactions.EscrowState.ABSENT;}
 private static List<ItemStack> loot(HolderLookup.Provider regs,List<NativeRawCell> before,BlockPos root,BlockPos mined,boolean creative,boolean coreDrop,boolean dropsEnabled,NativeBuilderDesigns.Design d,CoreLayout l){var out=new ArrayList<ItemStack>();if(mined.equals(root)){if(coreDrop)out.add(new ItemStack(NativeBuilderBindings.CORES.get(d.id())));var source=before.stream().filter(c->c.pos.equals(root)).findFirst().orElseThrow().tile();for(var stack:NativeBuilderData.read(source.getCompound("Inventory"),regs,d.id(),source.getCompound("Synthesis").getInt("Mode")==1))if(!stack.isEmpty())out.add(stack.copy());if(source.getCompound("Synthesis").getBoolean("Active")&&source.getCompound("Synthesis").getInt("Mode")!=1)out.add(new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vandorlabs",com.vandorlabs.machines.BuilderRecipeCatalog.input(d.id())))));}else if(!creative&&dropsEnabled){for(int x=0;x<d.width();x++)for(int y=0;y<d.height();y++)for(int z=0;z<d.depth();z++)if(root.offset(l.x(x,z),y,l.z(x,z)).equals(mined)&&l.frame(x,y,z))out.add(new ItemStack(NativeBuilderFormation.matter()));}return List.copyOf(out);}
 @SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.LOWEST) public static void breaking(net.neoforged.neoforge.event.level.BlockEvent.BreakEvent e){if(e.isCanceled()||!(e.getLevel() instanceof ServerLevel w)||!(e.getPlayer() instanceof ServerPlayer actor))return;var owner=NativeBuilderBindings.ownerAt(w,e.getPos());if(owner==null||!owner.formed()&&!owner.ownsRecovery())return;e.setCanceled(true);if(owner.transactionBlocked())return;try{mine(owner,actor,e.getPos());}catch(IllegalArgumentException refused){actor.displayClientMessage(net.minecraft.network.chat.Component.literal(refused.getMessage()),true);}}
 @SubscribeEvent public static void tick(LevelTickEvent.Post e){if(!(e.getLevel() instanceof ServerLevel world))return;var pending=QUEUED.get(world);if(pending==null)return;for(var q:List.copyOf(pending.values()))try{if(NativeCellTransactions.submit(world,FAMILY,q.actor,q.request)!=null)pending.remove(q.owner.getBlockPos());}catch(RuntimeException bad){pending.remove(q.owner.getBlockPos());q.owner.pending(false);q.actor.displayClientMessage(net.minecraft.network.chat.Component.literal(bad.getMessage()==null?"Builder operation refused":bad.getMessage()),true);}if(pending.isEmpty())QUEUED.remove(world);}
 @SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.LevelEvent.Unload e){if(e.getLevel() instanceof ServerLevel world)QUEUED.remove(world);}
 private NativeBuilderTransactions(){}
}
